<script lang="ts">
    import { getContext, onMount, type Snippet } from 'svelte';
    import type { AddBeforeSubmitFn } from './types.js';
    import imageCompressionModule, { type Options as ImageCompressionOptions } from 'browser-image-compression';
    import { fade } from 'svelte/transition';

    // Handle ESM/CJS interop for browser-image-compression
    type ImageCompressionFn = (image: File, options: ImageCompressionOptions) => Promise<File>;
    const imageCompression: ImageCompressionFn = (imageCompressionModule as unknown as { default?: ImageCompressionFn }).default ?? imageCompressionModule as unknown as ImageCompressionFn;
	import { addToast } from "../components/toasts.svelte.js";

    /**
     * @description
     * An image upload component with client-side compression, progress indicator and
     * optional remove button. Supports square, circle and banner display shapes.
     * Uploads to a presigned URL via `PUT`.
     *
     * @cssprop --max-image-width -- Maximum width of the image preview (used in the grid layout).
     *
     * @example
     * <ImageUpload
     *   uploadUrl="/api/upload"
     *   name="avatar"
     *   button="Upload"
     *   shape="circle"
     *   src={user.avatarUrl}
     * />
     */
    let {
        src,
        uploadUrl,
        name,
        id = `ImageUpload-${name}`,
        title = name,
        button,
        maxSize = 256000,
        compressSize = 0.5, // MB
        compressMaxWidth = 512, // px
        accept = 'image/png,image/svg+xml,image/jpg',
        removable = false,
        shape = 'square',
        onFile,
        children,
    }: {
        /** Current image source URL. */
        src?: string | null;
        /** The presigned URL to upload the image to. */
        uploadUrl: string;
        /** The form field name for the resulting URL value. */
        name: string;
        /** HTML id for the file input. */
        id?: string;
        /** Title used in the alt text of the preview image. */
        title?: string;
        /** Label for the upload button. */
        button: string;
        /** Maximum file size in bytes before compression is applied. */
        maxSize?: number;
        /** Maximum compressed file size in megabytes. */
        compressSize?: number;
        /** Maximum compressed image width in pixels. */
        compressMaxWidth?: number;
        /** Accepted MIME types for the file input. */
        accept?: string;
        /** Whether a remove button is shown. */
        removable?: boolean;
        /** Display shape of the image preview. */
        shape?: 'square' | 'circle' | 'banner';
        /** Callback invoked with the selected file before upload. */
        onFile?: (file: File) => void;
        /** Optional additional content rendered below the actions. */
        children?: Snippet;
    } = $props();

    let files: FileList | null = $state(null);
    let el: HTMLElement | null = $state(null);
    let urlEl: HTMLInputElement | null = $state(null);
    let error: string | null = $state(null);
    let resizeProgress = $state(0);
    let uploadState: 'idle' | 'resizing' | 'uploading' = $state('idle');

    const beforesubmit: AddBeforeSubmitFn = getContext('form.beforesubmit');

    beforesubmit(id, async ({ data, cancel }) => {
        if (!files || !files[0]) {
            return;
        }
        try {
            uploadState = 'resizing';
            resizeProgress = 0;
            const compressedFile = await imageCompression(files[0], {
                maxSizeMB: compressSize,
                maxWidthOrHeight: compressMaxWidth,
                useWebWorker: true,
                onProgress: (progress: number) => resizeProgress = progress,
            });
            uploadState = 'uploading';

            const response = await fetch(uploadUrl, {
                method: 'PUT',
                headers: {
                    'Content-Type': files[0].type,
                },
                body: compressedFile,
            });
            uploadState = 'idle';
            if(!response.ok) {
                addToast({ content: 'Something went wrong. Please try again.', autoClose: 3000 })
                cancel();
            }
            const imgUrl = new URL(response.url).href.split('?')[0];
            data.set(name, imgUrl);
            src = imgUrl;
        } catch(err) {
            addToast({ content: 'Something went wrong. Please try again.', autoClose: 3000 })
            cancel();
        }
    });

    function handleFile(event: Event) {
        error = null;
        const file = files ? files[0] : null;
        if (file && file.type.startsWith('image/') && file.size < maxSize) {
            if(onFile) onFile(file);
            src = URL.createObjectURL(file);
            /*
            // show preview
            const reader = new FileReader();
            reader.onload = (e) => {
                if (e.target) {
                    src = e.target.result as string;
                    //dispatch('filedata', e.target.result);
                }
            };
            reader.readAsDataURL(file);
            */
        }
        else if(file && file.type.startsWith('image/') && file.size > maxSize) {
            error = `Image must be less than ${maxSize/1024/1024}MB.`
        }
        else {
            error = `File must be an image.`
        }
    }

    function remove(e: MouseEvent) {
        e.preventDefault();
        e.stopPropagation();
        src = '';
        files = null;
    }

    function pick(e: MouseEvent) {
        e.preventDefault();
        e.stopPropagation();
        el!.click();
    }

    let jsEnabled = $state(false);

    onMount(() => {
        jsEnabled = true;
    });

</script>

<div class="ImageUpload {shape}">
    <div class="Image">
        {#if src}
            <img src={src} alt="{title} logo" />
        {/if}
        {#if uploadState !== 'idle'}
            <div class="Loading" in:fade={{ duration: 100 }} out:fade={{ duration: 100 }}>
                {#if uploadState === 'resizing'}
                    <small>Resizing.. {resizeProgress}%</small>
                {:else if uploadState === 'uploading'}
                    <small>Uploading..</small>
                {/if}
            </div>
        {/if}
    </div>
    <div class="ImageUploadActions" style="{!jsEnabled ? 'display: none;' : ''}">
        {#if children}
            <div class="description">
                {@render children()}
            </div>
        {/if}
        <button type="button" class="button outlined" onclick={pick}>
            {button}
        </button>
        {#if removable && src}
            <button type="button" class="button warn" onclick={remove}>
                Remove
            </button>
        {/if}
        {#if error}
            <div class="error">
                <small>{error}</small>
            </div>
        {/if}
        <input
            type="file"
            {accept}
            {id}
            bind:files
            onchange={handleFile}
            bind:this={el}
        />
        <input type="hidden" {name} value={src} bind:this={urlEl} />
    </div>
    <noscript>
        <small>Sorry, you need to enable Javascript to upload images.</small>
    </noscript>
</div>

<style>
    .ImageUpload {
        display: grid;
        grid-template-columns: 1fr;
        align-items: center;
        gap: var(--space-md);
        container-type: inline-size;
    }
    .Image {
        border: var(--border-size-thin) solid var(--border-color-subtle);
        pointer-events: none;
        position: relative;
        display: none;
    }
    .Image:has(img) {
        display: block;
    }
    .Image img {
        display: block;
        object-fit: contain;
        width: 100%;
        height: 100%;
    }
    .ImageUpload.square .Image img {
        object-fit: cover;
    }
    .ImageUpload.circle .Image {
        border-radius: 50%;
        overflow: hidden;
    }
    .ImageUpload.circle .Image img {
        object-fit: cover;
    }
    .placeholder {
        display: flex;
        align-items: center;
        justify-content: center;
        height: 100%;
        width: 100%;
        object-fit: contain;
        padding: var(--space-md);
        text-align: center;
        border: var(--border-size-thin) dashed var(--border-color);
        border-radius: var(--border-radius-base);
    }
    .Loading {
        position: absolute;
        inset: 0;
        z-index: 5;
        backdrop-filter: var(--scrim-backdrop-filter);
        background: var(--scrim-background);
        display: flex;
        align-items: center;
        justify-content: center;
        flex-direction: column;
        gap: var(--space-md);
        padding: var(--space-md);
    }
    input {
        display: none;
    }
    .error {
        margin-block-start: var(--space-sm);
    }
    .ImageUpload.banner {
        grid-template-areas: "image";
        width: 100%;
    }
    .ImageUpload.banner .Image {
        height: 100%;
        grid-area: image;
        overflow: hidden;
        object-fit: cover;
        height: 15rem;
    }
    .ImageUpload.banner .Image img {
        object-fit: cover;
    }
    .ImageUpload.banner .ImageUploadActions {
        display: flex;
        grid-area: image;
        flex-direction: column;
        justify-content: center;
        padding: var(--space-md);
    }
    .ImageUpload.banner:hover .ImageUploadActions {
        background: var(--scrim-background);
    }
    .ImageUploadActions {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: var(--space-sm);
        align-items: start;
    }
    @container (min-width: 320px) {
        .ImageUpload:not(.banner) {
            grid-template-columns: minmax(auto, var(--max-image-width)) 1fr;
            gap: var(--space-xl);
        }
        .ImageUpload.banner .ImageUploadActions {
            padding: var(--space-xxl);
        }
        .ImageUploadActions {
            grid-template-columns: 1fr;
            gap: var(--space-md);
        }
    }
</style>
